#include <iostream>
class Base {
protected:
    int protected_member;
public:
    Base() : protected_member(0) {}
};
class Derived : public Base {
public:
    void setProtectedMember(int value) {
        protected_member = value; // Accessing protected member from derived class
    }
    void display() {
        std::cout << "Protected member value: " << protected_member << std::endl;
    }
};
int main() {
    Derived obj;
    obj.setProtectedMember(42);
    obj.display();
    // std::cout << obj.protected_member; // Error: protected_member is not accessible here
    return 0;
}
